function crearPar(primero, segundo) {
  return [primero, segundo];
}

function calcularTotal(minutosPorDia, cantidadDias) {
  return minutosPorDia * cantidadDias;
}

function ampliarCinco(cantidad) {
  return cantidad + 5;
}

function minutosValidos(texto) {
  const valor = Number(texto);
  return texto.trim() !== "" && Number.isInteger(valor) && valor >= 0 && valor <= 120;
}

function recomendar(cantidad) {
  if (cantidad >= 60) { return "Intensivo"; }
  if (cantidad >= 30) { return "Constante"; }
  return "Inicio";
}

function sumarSesiones(datos) {
  let total = 0;
  let i = 0;
  while (i < datos.length) {
    total = total + datos[i];
    i = i + 1;
  }
  return total;
}

function contarSesiones(datos, objetivo) {
  let cantidad = 0;
  for (let i = 0; i < datos.length; i = i + 1) {
    if (datos[i] >= objetivo) { cantidad = cantidad + 1; }
  }
  return cantidad;
}

function maximo(datos) {
  if (datos.length === 0) { return "Sin datos"; }
  let mayor = datos[0];
  let i = 1;
  while (i < datos.length) {
    if (datos[i] > mayor) { mayor = datos[i]; }
    i = i + 1;
  }
  return mayor;
}

function resumir(datos, objetivo) {
  return crearPar(sumarSesiones(datos), contarSesiones(datos, objetivo));
}

const nombre = prompt("Tu nombre");
const meta = prompt("Tu meta");
const textoMinutos = prompt("Minutos diarios");
const minutos = Number(textoMinutos);
const textoDias = prompt("Días del plan");
const dias = Number(textoDias);
const referencia = 20;
if (minutosValidos(textoMinutos) && textoDias.trim() !== "" && Number.isInteger(dias) && dias >= 0 && dias <= 7) {
  const textoCantidad = prompt("Cantidad de sesiones realizadas");
  const cantidadRegistros = Number(textoCantidad);
  const registros = [];
  if (textoCantidad.trim() !== "" && Number.isInteger(cantidadRegistros) && cantidadRegistros >= 0 && cantidadRegistros <= 10) {
    let registrosValidos = true;
    for (let i = 0; i < cantidadRegistros; i = i + 1) {
      const textoRegistro = prompt("Minutos realizados");
      if (minutosValidos(textoRegistro)) {
        registros.push(Number(textoRegistro));
      } else { registrosValidos = false; }
    }
    if (registrosValidos) {
      const total = calcularTotal(minutos, dias);
      const minutosAmpliados = ampliarCinco(minutos);
      const totalAmpliado = calcularTotal(ampliarCinco(minutos), dias);
      const tipoMinutos = typeof minutos;
      const horas = total / 60;
      const restoDiez = minutos % 10;
      const recomendacion = recomendar(minutos);
      console.log("Hola TeslaCode");
      console.log("Mi plan de práctica");
      console.log("Estado: listo");
      console.log("Sesión: JavaScript");
      console.log("Minutos diarios:", minutos);
      console.log("Días:", dias);
      console.log("Meta:", meta);
      console.log("Recordatorio:", meta);
      console.log("Referencia diaria:", referencia);
      console.log("Total:", total);
      console.log("Nombre:", nombre);
      console.log("Plan con 5 más:", totalAmpliado);
      console.log("Tipo de minutos:", tipoMinutos);
      console.log("Horas previstas:", horas);
      console.log("Resto de 10:", restoDiez);
      console.log("Disponible hasta 120:", 120 - minutos);
      console.log("Alcanza 30:", 30 <= minutos);
      console.log("Igual a referencia:", referencia === minutos);
      console.log("Distinto de referencia:", referencia !== minutos);
      console.log("Recomendación:", recomendacion);
      console.log("Sesiones programadas:", dias);
      let programados = 0;
      let pares = 0;
      for (let i = 0; i < dias; i = i + 1) {
        const dia = i + 1;
        console.log("Día:", dia);
        programados = programados + minutos;
        if (dia % 2 === 0) { pares = pares + 1; }
      }
      console.log("Minutos programados:", programados);
      console.log("Días pares:", pares);
      console.log("Sesiones realizadas:", registros.length);
      console.log("Registros:", registros);
      const resumen = resumir(registros, minutos);
      console.log("Minutos realizados:", resumen[0]);
      console.log("Sesiones con meta:", resumen[1]);
      console.log("Máximo realizado:", maximo(registros));
    } else { console.log("Entrada inválida"); }
  } else { console.log("Entrada inválida"); }
} else { console.log("Entrada inválida"); }

function primeraSesion(datos, meta) {
  let resultado = "Sin coincidencia";
  for (const valor of datos) {
    if (valor >= meta) { resultado = valor; break; }
  }
  return resultado;
}

function totalAjustado(uno, dos, extra) {
  function aplicar(a, b, regla) { return regla(a) + regla(b); }
  return aplicar(uno, dos, valor => valor + extra);
}

function segundosPorSesion(datos) {
  return datos.map(minutos => minutos * 60);
}

function diagnosticoMeta(datos, meta) {
  const cumple = valor => valor >= meta;
  const primera = datos.find(cumple);
  return [datos.filter(cumple), primera === undefined ? null : primera, datos.some(cumple), datos.every(cumple)];
}

function excedenteTotal(datos, meta) {
  return datos.reduce((total, valor) => total + (valor > meta ? valor - meta : 0), 0);
}

function rotuloTema(texto) {
  const tema = texto.trim().normalize("NFC").toLowerCase();
  const visible = tema === "" ? "Sin tema" : tema;
  return `Tema: ${visible}`;
}

function cambiarDuracion(registro, minutos) {
  return { ...registro, minutos };
}

function minutosDelModo(modo, detalle) {
  let base;
  switch (modo) {
    case "normal": base = 25; break;
    case "rapido": base = 10; break;
    default: base = 15;
  }
  return detalle?.minutos ?? base;
}

function importarMinutos(texto) {
  try {
    const datos = JSON.parse(texto);
    if (!Array.isArray(datos) || !datos.every(n => Number.isInteger(n) && n >= 0 && n <= 120)) return null;
    return datos;
  } catch { return null; }
}

function totalesPorTema(registros) {
  const mapa = new Map();
  for (const dato of registros) {
    mapa.set(dato.tema, (mapa.get(dato.tema) ?? 0) + dato.minutos);
  }
  return [...mapa];
}

function mejorRacha(datos, meta) {
  let actual = 0;
  let mejor = 0;
  for (const valor of datos) {
    actual = valor >= meta ? actual + 1 : 0;
    mejor = Math.max(mejor, actual);
  }
  return mejor;
}

function pasosMitad(opciones) {
  let pasos = 0;
  for (; opciones > 1; opciones = Math.ceil(opciones / 2)) pasos += 1;
  return pasos;
}

function contieneDuracion(datos, objetivo) {
  let inicio = 0;
  let fin = datos.length - 1;
  while (inicio <= fin) {
    const medio = Math.floor((inicio + fin) / 2);
    if (datos[medio] === objetivo) return true;
    if (datos[medio] < objetivo) inicio = medio + 1;
    else fin = medio - 1;
  }
  return false;
}

function ordenarDuraciones(datos) {
  return datos.toSorted((a, b) => a - b);
}

function picoSemanal(datos, k) {
  if (k < 1 || k > datos.length) return null;
  let total = 0;
  for (let i = 0; i < k; i += 1) total += datos[i];
  let mejor = total;
  for (let i = k; i < datos.length; i += 1) {
    total += datos[i] - datos[i - k];
    mejor = Math.max(mejor, total);
  }
  return mejor;
}

function minutosDelArbol(nodo) {
  if (nodo === null) return 0;
  return nodo.hijos.reduce((total, hijo) => total + minutosDelArbol(hijo), nodo.minutos);
}

function primeraTareaEnNivel(raiz, objetivo) {
  if (raiz === null) return null;
  const cola = [[raiz, 0]];
  for (let i = 0; i < cola.length; i += 1) {
    const [nodo, nivel] = cola[i];
    if (nivel === objetivo) return nodo.id;
    for (const hijo of nodo.hijos) cola.push([hijo, nivel + 1]);
  }
  return null;
}

function tareasAlcanzables(conexiones, inicio) {
  const orden = [inicio];
  const vistos = new Set(orden);
  for (let i = 0; i < orden.length; i += 1) {
    const id = orden[i];
    for (const vecino of (Object.hasOwn(conexiones, id) ? conexiones[id] : [])) {
      if (vistos.has(vecino)) continue;
      vistos.add(vecino);
      orden.push(vecino);
    }
  }
  return orden;
}

function probarContadores(inicio, cambios) {
  const crear = base => {
    let total = base;
    return valor => { total += valor; return total; };
  };
  const primero = crear(inicio);
  const segundo = crear(0);
  return [primero(cambios[0]), segundo(cambios[1]), primero(cambios[2])];
}

function duracionDeSesion(inicio, cambios) {
  class Sesion {
    constructor(minutos) { this.total = minutos; }
    agregar(valor) { this.total += valor; return this.total; }
  }
  const sesion = new Sesion(inicio);
  return cambios.map(valor => sesion.agregar(valor));
}

function fechaEnZona(iso, zona) {
  const partes = new Intl.DateTimeFormat("en", { timeZone: zona, year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(new Date(iso));
  const leer = tipo => partes.find(parte => parte.type === tipo).value;
  return `${leer("year")}-${leer("month")}-${leer("day")}`;
}

function siguienteCodigo(texto, salto) {
  const siguiente = BigInt(texto) + BigInt(salto);
  return String(siguiente);
}

