  return total;
}

function contarSesiones(datos, objetivo) {
  let cantidad = 0;
  for (let i = 0; i < datos.length; i = i + 1) {
    if (datos[i] >= objetivo) { cantidad = cantidad + 1; }
  }
  return cantidad;
}

function maximo(datos) {
  if (datos.length === 0) { return "Sin datos"; }
  let mayor = datos[0];
  let i = 1;
  while (i < datos.length) {
    if (datos[i] > mayor) { mayor = datos[i]; }
    i = i + 1;
  }
  return mayor;
}

